import type { IncomingMessage, ServerResponse } from 'http';
// Twilio signs the exact form body; retain raw bytes for provider signature validation.
export const config = { api: { bodyParser: false } };
// @ts-ignore - generated by npm run build
import { handleCoreApi } from '../../../core-server.bundle.js';

type RequestWithBody = IncomingMessage & { body?: any; rawBody?: Buffer };

export default async function handler(req: RequestWithBody, res: ServerResponse) {
  try {
    if (req.method === 'POST') {
      const chunks: Buffer[] = [];
      for await (const chunk of req) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
      const raw = Buffer.concat(chunks);
      req.rawBody = raw;
      const contentType = String(req.headers['content-type'] || '').toLowerCase();
      if (contentType.includes('application/x-www-form-urlencoded')) {
        const params = new URLSearchParams(raw.toString('utf8'));
        const form: Record<string, string> = {};
        params.forEach((value, key) => { form[key] = value; });
        req.body = form;
      } else {
        try { req.body = JSON.parse(raw.toString('utf8') || '{}'); }
        catch {
          res.statusCode = 400;
          res.setHeader('Content-Type', 'application/json');
          return res.end(JSON.stringify({ error: 'Invalid WhatsApp webhook payload.' }));
        }
      }
    } else {
      req.body = {};
    }
    const incomingUrl = req.url || '/';
    const queryIndex = incomingUrl.indexOf('?');
    const query = queryIndex >= 0 ? incomingUrl.slice(queryIndex) : '';
    const params = (req as any).query || {};
    const provider = String(params.provider || '').toUpperCase();
    const routeId = String(params.routeId || '');
    req.url = '/api/webhooks/whatsapp/' + provider + '/' + routeId + query;
    const handled = await handleCoreApi(req, res);
    if (!handled && !res.writableEnded) { res.statusCode = 404; res.end(); }
  } catch (error: any) {
    console.error('[WhatsApp provider webhook] Failed:', error?.message || error);
    if (!res.writableEnded) {
      res.statusCode = 500;
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify({ error: 'WhatsApp webhook processing failed.' }));
    }
  }
}
